style.css:
@-moz-document domain("roblox.com") {
/* Helt svart bakgrund */
    html, body {
        background-color: black !important;
    }

    /* Bild i mitten */
    body::before {
        content: "";
        position: fixed;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);

        width: 400px;  /* ändra storlek här */
        height: 400px;

        background-image: url(https://i.pinimg.com/736x/12/94/31/12943128d3f633a2a2446ccbf9d68e2b.jpg) !important;
        background-repeat: no-repeat !important;
        background-size: contain !important;
        background-position: center !important;

        z-index: -1; /* ligger bakom allt */
        pointer-events: none;
    }

    /* Gör Roblox transparent så man ser bilden */
    #container, .main-content, .navbar {
        background: transparent !important;
    }
}
